// imports: import asyncio; import time; from dataclasses import asdict, dataclass, field; from datetime import datetime, timezone; from statistics import mean; from typing import Any; from evals.dataset import EvalCase; from evals.judges import JudgeVerdict, judge_answer; from evals.metrics import (     RetrievalMetrics,     aggregate_retrieval,     citation_validity,     evaluate_retrieval,     keyword_coverage, ); from reposage.agents.engine import CodebaseAgent; from reposage.agents.prompts import PROMPT_VERSION; from reposage.config import Settings, get_settings
    async def run_ablation(
        self, cases: list[EvalCase], variants: tuple[Variant, ...] = ABLATION
    ) -> list[VariantResult]:
        """Score each retrieval configuration over the whole dataset."""
        results: list[VariantResult] = []
        for variant in variants:
            tracer = Tracer()
            started = time.perf_counter()
            per_case: list[RetrievalMetrics] = []

            with use_tracer(tracer):
                for case in cases:
                    try:
                        chunks, _ = await self.retriever.retrieve(
                            case.question,
                            top_k=self.settings.top_k,
                            rerank=variant.rerank,
                            expand_neighbours=variant.neighbours,
                            mode=variant.mode,
                        )
                        paths: list[str] = []
                        for scored in chunks:
                            if scored.chunk.path not in paths:
                                paths.append(scored.chunk.path)
                    except Exception as exc:
                        log.warning("ablation.case_failed", case=case.id, error=str(exc)[:160])
                        paths = []
                    per_case.append(
                        evaluate_retrieval(
                            case.id, paths, case.expected_paths, k=self.settings.top_k
                        )
                    )

            results.append(
                VariantResult(
                    name=variant.name,
                    description=variant.description,
                    aggregate=aggregate_retrieval(per_case),
                    per_case=[m.as_dict() for m in per_case],
                    elapsed_seconds=round(time.perf_counter() - started, 2),
                    usage=tracer.usage.model_dump(),
                )
            )
            log.info(
                "ablation.variant_done",
                variant=variant.name,
                **{
                    k: v
                    for k, v in results[-1].aggregate.items()
                    if k in ("hit_rate", "recall@k", "mrr")
                },
            )
        return results

