// imports: import argparse; import asyncio; import sys; from pathlib import Path; import orjson; from evals.dataset import DEFAULT_DATASET, load_dataset; from evals.harness import EvalReport, EvalRunner; from evals.report import render_report; from reposage.config import get_settings; from reposage.index.store import RepoIndex; from reposage.llm.client import close_client, get_client; from reposage.logging_setup import configure_logging, get_logger
def run_cli(repo: str, dataset: Path | None, limit: int | None, output: Path | None) -> None:
    """Entry point used by ``reposage eval``."""
    argv = ["--repo", repo]
    if dataset:
        argv += ["--dataset", str(dataset)]
    if limit:
        argv += ["--limit", str(limit)]
    if output:
        argv += ["--output", str(output)]
    raise SystemExit(main(argv))

