// imports: import asyncio; import time; from collections.abc import AsyncIterator; from typing import Any; from reposage.agents.graph import build_graph, describe_graph; from reposage.agents.state import AgentDeps, initial_state; from reposage.config import Settings, get_settings; from reposage.index.retriever import HybridRetriever; from reposage.index.store import RepoIndex; from reposage.llm.client import LLMClient, get_client; from reposage.logging_setup import get_logger; from reposage.models import AgentAnswer, Citation
    async def batch(self, questions: list[str], concurrency: int = 3) -> list[AgentAnswer]:
        """Answer several questions with bounded parallelism (used by evals)."""
        semaphore = asyncio.Semaphore(max(1, concurrency))

        async def _one(question: str) -> AgentAnswer:
            async with semaphore:
                return await self.ask(question)

        return await asyncio.gather(*(_one(q) for q in questions))

