// imports: from functools import partial; from typing import Any; from langgraph.graph import END, START, StateGraph; from reposage.agents.nodes import (     analyst_node,     critic_node,     finalizer_node,     planner_node,     retriever_node, ); from reposage.agents.state import AgentDeps, AgentState; from reposage.logging_setup import get_logger
def route_after_plan(state: AgentState) -> str:
    """Skip retrieval for questions the repository map already answers."""
    plan = state.get("plan")
    if plan is not None and not plan.needs_retrieval:
        return NODE_ANALYSE
    return NODE_RETRIEVE

