def _symbol_at(index, path: str, start: int, end: int) -> str | None:
    for chunk in index.chunks_for_path(path):
        if chunk.start_line <= start <= chunk.end_line and chunk.symbol:
            return chunk.qualified_name
    _ = end
    return None

