def _l2_normalise(matrix: np.ndarray) -> np.ndarray:
    """Unit-normalise rows so cosine similarity reduces to a dot product."""
    norms = np.linalg.norm(matrix, axis=1, keepdims=True)
    np.maximum(norms, 1e-12, out=norms)
    return matrix / norms

