// imports: import re; from dataclasses import dataclass; from functools import lru_cache; from typing import Any; from reposage.ingest.languages import LanguageSpec, get_spec; from reposage.logging_setup import get_logger; from reposage.models import Chunk, ChunkKind
    def _chunk_markdown(self, rel_path: str, content: str, spec: LanguageSpec) -> list[Chunk]:
        """Split prose on heading boundaries so sections stay intact."""
        lines = content.splitlines()
        if not lines:
            return []
        heading = re.compile(r"^(#{1,4})\s+(.*)$")
        sections: list[tuple[int, str]] = []
        for i, line in enumerate(lines):
            if match := heading.match(line):
                sections.append((i, match.group(2).strip()))
        header = f"// file: {rel_path} (documentation)\n"
        if not sections:
            return self._window(
                rel_path,
                lines,
                0,
                len(lines) - 1,
                spec,
                ChunkKind.DOCUMENTATION,
                None,
                header,
                None,
            )

        chunks: list[Chunk] = []
        if sections[0][0] > 0:
            chunks.extend(
                self._window(
                    rel_path,
                    lines,
                    0,
                    sections[0][0] - 1,
                    spec,
                    ChunkKind.DOCUMENTATION,
                    "preamble",
                    header,
                    None,
                )
            )
        for index, (start, title) in enumerate(sections):
            end = sections[index + 1][0] - 1 if index + 1 < len(sections) else len(lines) - 1
            if end < start:
                continue
            chunks.extend(
                self._window(
                    rel_path, lines, start, end, spec, ChunkKind.DOCUMENTATION, title, header, None
                )
            )
        return chunks

