_JSON_FENCE = re.compile(r"```(?:json)?\s*(.*?)```", re.DOTALL)

// file: src/reposage/llm/gemini.py (python)
// imports: import asyncio; import re; from collections.abc import AsyncIterator; from typing import Any; import httpx; import orjson; from reposage.llm.base import (     ContentBlockedError,     LLMError,     LLMResponse,     Message,     RateLimitError,     TransientLLMError, ); from reposage.logging_setup import get_logger
def extract_json(text: str) -> Any:
    """Best-effort recovery of a JSON value from a model response.

    Models wrap JSON in prose or fences even when asked not to. Rather than
    failing the run we escalate through progressively more forgiving strategies:
    direct parse, fenced block, then balanced-brace scanning.
    """
    text = (text or "").strip()
    if not text:
        raise ValueError("empty response")

    try:
        return orjson.loads(text)
    except orjson.JSONDecodeError:
        pass

    if match := _JSON_FENCE.search(text):
        try:
            return orjson.loads(match.group(1).strip())
        except orjson.JSONDecodeError:
            pass

    for opener, closer in (("{", "}"), ("[", "]")):
        start = text.find(opener)
        if start == -1:
            continue
        depth = 0
        in_string = False
        escaped = False
        for index in range(start, len(text)):
            char = text[index]
            if escaped:
                escaped = False
                continue
            if char == "\\":
                escaped = True
                continue
            if char == '"':
                in_string = not in_string
                continue
            if in_string:
                continue
            if char == opener:
                depth += 1
            elif char == closer:
                depth -= 1
                if depth == 0:
                    try:
                        return orjson.loads(text[start : index + 1])
                    except orjson.JSONDecodeError:
                        break
    raise ValueError(f"could not parse JSON from response: {text[:200]!r}")

