def _strip_prefix(path: str) -> str:
    """Remove git's ``a/`` or ``b/`` prefix and any trailing tab metadata."""
    path = path.split("\t")[0].strip()
    for prefix in ("a/", "b/"):
        if path.startswith(prefix):
            return path[2:]
    return path

