// imports: import os; from dataclasses import dataclass; from typing import Any; import httpx; import orjson; from reposage.logging_setup import get_logger; from reposage.models import ReviewReport, Severity
    async def _find_marked_comment(self, ref: PullRequestRef) -> int | None:
        response = await self._request(
            "GET",
            f"/repos/{ref.owner}/{ref.repo}/issues/{ref.number}/comments",
            params={"per_page": 100},
        )
        for comment in response.json():
            if MARKER in (comment.get("body") or ""):
                return int(comment["id"])
        return None

