// imports: import asyncio; import time; from typing import TYPE_CHECKING; from pydantic import BaseModel, Field; from reposage.agents.prompts import (     REVIEW_SUMMARY_SYSTEM,     REVIEWER_SYSTEM,     REVIEWER_USER,     format_context, ); from reposage.config import Settings, get_settings; from reposage.llm.client import LLMClient, ModelTier; from reposage.logging_setup import get_logger; from reposage.models import ReviewFinding, ReviewReport, Severity; from reposage.observability import current_tracer; from reposage.review.diff import DiffFile, ParsedDiff, parse_unified_diff
def _deduplicate(findings: list[ReviewFinding]) -> list[ReviewFinding]:
    """Collapse findings that repeat the same point at the same location."""
    seen: dict[tuple[str, int, str], ReviewFinding] = {}
    for finding in findings:
        key = (finding.path, finding.line or -1, finding.title.lower()[:60])
        existing = seen.get(key)
        if existing is None or finding.confidence > existing.confidence:
            seen[key] = finding
    return sorted(seen.values(), key=lambda f: (f.severity.rank, f.path, f.line or 0))

