  const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) =>
    ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

  function toast(message, isError = false) {
    const el = $("toast");
    el.textContent = message;
    el.className = "toast show" + (isError ? " err" : "");
    clearTimeout(el._t);
    el._t = setTimeout(() => (el.className = "toast"), 3600);
  }

  async function api(path, options) {
    const response = await fetch(path, options);
    if (!response.ok) {
      let detail = response.statusText;
      try { detail = (await response.json()).detail || detail; } catch (_) {}
      throw new Error(detail);
    }
    return response.json();
  }

  /**
   * Minimal markdown renderer. Deliberately hand-rolled: the answer format is
   * narrow and known, so a short renderer beats shipping a full parser to the
   * browser. Citation markers become clickable chips.
   */
  function renderMarkdown(src) {
    const blocks = [];
    let text = String(src || "").replace(/```(\w*)\n?([\s\S]*?)```/g, (_, lang, code) => {
      blocks.push("<pre><code>" + esc(code.replace(/\n$/, "")) + "</code></pre>");
      return " BLOCK" + (blocks.length - 1) + " ";
    });

    text = esc(text)
      .replace(/\[([^\[\]\s]+?\.[A-Za-z0-9_]+):(\d+)(?:\s*-\s*(\d+))?\]/g,
        (_, path, start, end) =>
          '<span class="cite" data-path="' + path + '" data-line="' + start + '">'
          + path + ":" + start + (end ? "-" + end : "") + "</span>")
      .replace(/`([^`\n]+)`/g, "<code>$1</code>")
      .replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>")
      .replace(/(^|[\s(])\*([^*\n]+)\*/g, "$1<em>$2</em>")
      .replace(/\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener">$1</a>');

    const out = [];
    let list = null;
    const closeList = () => { if (list) { out.push("</" + list + ">"); list = null; } };
    for (const raw of text.split("\n")) {
      const line = raw.trimEnd();
      const heading = line.match(/^(#{1,4})\s+(.*)$/);
      const bullet = line.match(/^\s*[-*+]\s+(.*)$/);
      const numbered = line.match(/^\s*\d+[.)]\s+(.*)$/);

      if (heading) { closeList(); const n = heading[1].length; out.push("<h" + n + ">" + heading[2] + "</h" + n + ">"); }
      else if (bullet) { if (list !== "ul") { closeList(); out.push("<ul>"); list = "ul"; } out.push("<li>" + bullet[1] + "</li>"); }
      else if (numbered) { if (list !== "ol") { closeList(); out.push("<ol>"); list = "ol"; } out.push("<li>" + numbered[1] + "</li>"); }
      else if (/^\s*&gt;\s?/.test(line)) { closeList(); out.push("<blockquote>" + line.replace(/^\s*&gt;\s?/, "") + "</blockquote>"); }
      else if (!line.trim()) { closeList(); }
      else { closeList(); out.push("<p>" + line + "</p>"); }
    }
    closeList();
    return out.join("\n").replace(/ BLOCK(\d+) /g, (_, i) => blocks[+i]);
  }

  async function loadHealth() {
    const pill = $("model-pill").querySelector(".dot");
    try {
      const health = await api("/api/health");
      const configured = health.llm.configured;
      pill.className = "dot " + (configured ? "ok" : "warn");
      $("model-text").textContent = configured
        ? health.llm.deep_model + " · v" + health.version
        : "GEMINI_API_KEY not set";
      if (!configured) toast("Set GEMINI_API_KEY in your .env file to enable the model.", true);
    } catch (err) {
      pill.className = "dot err";
      $("model-text").textContent = "API unreachable";
    }
  }

  async function loadIndexes() {
    try {
      state.indexes = (await api("/api/indexes")).indexes;
    } catch (err) { state.indexes = []; }

    const list = $("repo-list");
    if (!state.indexes.length) {
      list.innerHTML = '<div class="stat">No indexes yet. Build one above.</div>';
      return;
    }
    list.innerHTML = state.indexes.map((entry) =>
      '<button class="repo-item ' + (entry.id === state.repo ? "active" : "") + '" data-id="' + esc(entry.id) + '">'
      + '<div class="name">' + esc(entry.name) + "</div>"
      + '<div class="meta">' + entry.files.toLocaleString() + " files · "
      + entry.chunks.toLocaleString() + " chunks · " + esc(entry.commit || "local") + "</div></button>").join("");
    list.querySelectorAll(".repo-item").forEach((node) =>
      node.addEventListener("click", () => selectRepo(node.dataset.id)));

    if (!state.repo && state.indexes.length) selectRepo(state.indexes[0].id);
  }

