  function buildIndex() {
    const source = $("source-input").value.trim();
    if (!source) { toast("Enter a repository first.", true); return; }
    $("index-btn").disabled = true;
    $("index-progress").style.display = "";
    $("index-status").textContent = "resolving repository";

    const stream = new EventSource("/api/indexes/stream/build?source=" + encodeURIComponent(source));
    const LABELS = {
      "ingest.resolve": "cloning repository",
      "ingest.walk": "scanning files",
      "ingest.chunk": "parsing and chunking",
      "index.embed": "embedding chunks",
      "llm.embed": "embedding chunks",
      "index.lexical": "building lexical index",
    };
    const stop = () => {
      stream.close();
      $("index-btn").disabled = false;
      $("index-progress").style.display = "none";
    };
    stream.addEventListener("progress", (event) => {
      const payload = JSON.parse(event.data);
      if (payload.type === "span_start" && LABELS[payload.name]) {
        $("index-status").textContent = LABELS[payload.name];
      }
    });
    stream.addEventListener("complete", (event) => {
      const payload = JSON.parse(event.data);
      stop();
      $("source-input").value = "";
      toast("Indexed " + payload.name + ": " + payload.chunks.toLocaleString()
            + " chunks from " + payload.files.toLocaleString() + " files.");
      state.repo = payload.index;
      loadIndexes();
    });
    stream.addEventListener("error", (event) => {
      stop();
      let message = "Indexing failed.";
      try { message = JSON.parse(event.data).error; } catch (_) {}
      toast(message, true);
    });
    stream.onerror = stop;
  }

