  function traceStart(payload) {
    if (HIDDEN_SPANS.has(payload.name)) return;
    const row = document.createElement("div");
    row.className = "trace-row running";
    row.innerHTML = '<span class="glyph spin">◌</span><span class="label">'
      + esc(SPAN_LABELS[payload.name] || payload.name) + '</span><span class="ms"></span>';
    $("trace").appendChild(row);
    state.spans.set(payload.span_id, row);
  }

  function traceEnd(payload) {
    const row = state.spans.get(payload.span_id);
    if (!row) return;
    const attrs = payload.attributes || {};
    const failed = attrs.status === "error";
    row.className = "trace-row " + (failed ? "err" : "done");
    const glyph = row.querySelector(".glyph");
    glyph.className = "glyph";
    glyph.textContent = failed ? "✗" : "✓";
    row.querySelector(".ms").textContent = Math.round(payload.duration_ms) + "ms";

    const notes = [];
    if (attrs.queries) notes.push(attrs.queries + " queries");
    if (attrs.returned) notes.push(attrs.returned + " chunks");
    if (attrs.files) notes.push(attrs.files + " files");
    if (attrs.verdict) notes.push(attrs.verdict);
    if (attrs.citations !== undefined) notes.push(attrs.citations + " citations");
    if (notes.length) {
      const note = document.createElement("div");
      note.className = "trace-row log";
      note.innerHTML = '<span class="glyph"></span><span class="label">' + esc(notes.join(" · ")) + "</span>";
      row.insertAdjacentElement("afterend", note);
    }
  }

