  function renderPlan(plan) {
    if (!plan) return;
    $("plan-section").style.display = "";
    const parts = ['<div class="kv"><span>intent</span><span>' + esc(plan.intent || "") + "</span></div>"];
    (plan.sub_questions || []).forEach((sub) => parts.push('<div class="plan-q">' + esc(sub.question) + "</div>"));
    if (plan.path_hints && plan.path_hints.length) {
      parts.push('<div class="kv" style="margin-top:6px"><span>path hints</span><span>'
        + esc(plan.path_hints.slice(0, 3).join(", ")) + "</span></div>");
    }
    $("plan").innerHTML = parts.join("");
  }

  function renderUsage(usage, elapsed, refinements) {
