      ["output tokens", usage.completion_tokens.toLocaleString()],
      ["cache hits", usage.cache_hits],
      ["refinements", refinements],
      ["cost", "$" + usage.cost_usd.toFixed(5)],
    ].map(([k, v]) => '<div class="kv"><span>' + k + "</span><span>" + v + "</span></div>").join("");
  }

  function ask() {
    const question = $("question").value.trim();
    if (!question) return;
    if (!state.repo) { toast("Index a repository first.", true); return; }
    if (state.streaming) return;

    state.streaming = true;
    $("ask-btn").disabled = true;
    $("question").value = "";
    autosize();
    resetTrace();
    const emptyState = $("empty-state");
    if (emptyState) emptyState.remove();

    const block = document.createElement("div");
    block.className = "qa";
    block.innerHTML = '<div class="q">' + esc(question) + "</div>"
      + '<div class="answer"><span class="cursor"></span></div>'
      + '<div class="citations"></div><div class="answer-footer" style="display:none"></div>';
    $("conversation").appendChild(block);
    block.scrollIntoView({ behavior: "smooth", block: "start" });

    const answerEl = block.querySelector(".answer");
    let buffer = "";
    const stream = new EventSource("/api/ask/stream?repo=" + encodeURIComponent(state.repo)
      + "&q=" + encodeURIComponent(question));

    const finish = () => {
      stream.close();
      state.streaming = false;
      $("ask-btn").disabled = false;
    };

    stream.addEventListener("span_start", (e) => traceStart(JSON.parse(e.data)));
    stream.addEventListener("span_end", (e) => traceEnd(JSON.parse(e.data)));
    stream.addEventListener("token", (e) => {
      buffer += JSON.parse(e.data).attributes.text || "";
      answerEl.innerHTML = renderMarkdown(buffer) + '<span class="cursor"></span>';
      $("conversation").scrollTop = $("conversation").scrollHeight;
    });
    stream.addEventListener("final", (e) => {
      const data = JSON.parse(e.data).attributes;
      answerEl.innerHTML = renderMarkdown(data.answer || buffer);
      renderPlan(data.plan);
      renderUsage(data.usage, data.elapsed_seconds, data.refinement_rounds);

      const citations = data.citations || [];
      if (citations.length) {
        block.querySelector(".citations").innerHTML =
          '<div class="section-label" style="margin-top:16px">Sources</div>'
          + citations.map((c) =>
            '<div class="citation" data-path="' + esc(c.path) + '" data-line="' + c.start_line + '">'
            + '<span class="loc">' + esc(c.path) + ":" + c.start_line + "-" + c.end_line + "</span>"
            + '<span class="sym">' + esc(c.symbol || "") + "</span></div>").join("");
      }

      const confidence = data.confidence || 0;
      const colour = confidence >= 0.7 ? "var(--green)" : confidence >= 0.45 ? "var(--amber)" : "var(--red)";
      const tokens = (data.usage.prompt_tokens + data.usage.completion_tokens + data.usage.embedding_tokens);
      const footer = block.querySelector(".answer-footer");
      footer.style.display = "";
      footer.innerHTML =
        '<span class="conf" style="color:' + colour + '">confidence ' + Math.round(confidence * 100) + "%"
        + '<span class="conf-bar"><i style="width:' + Math.round(confidence * 100) + "%;background:" + colour + '"></i></span></span>'
        + '<span class="stat">' + data.elapsed_seconds.toFixed(1) + "s</span>"
        + '<span class="stat">' + tokens.toLocaleString() + " tokens</span>"
        + '<span class="stat">$' + data.usage.cost_usd.toFixed(5) + "</span>"
        + '<span class="stat">' + data.retrieved_paths.length + " files retrieved</span>"
        + (data.refinement_rounds ? '<span class="stat">' + data.refinement_rounds + " refinement(s)</span>" : "");
      finish();
    });
    stream.addEventListener("error", (e) => {
      let message = "The agent run failed.";
      try { message = JSON.parse(e.data).attributes.error; } catch (_) {}
      answerEl.innerHTML = '<p style="color:var(--red)">' + esc(message) + "</p>";
      toast(message, true);
      finish();
    });
    stream.onerror = () => {
      if (!state.streaming) return;
      const cursor = answerEl.querySelector(".cursor");
      if (cursor) cursor.remove();
      finish();
    };
  }

