  async function openSource(path, line) {
    try {
      const data = await api("/api/source/" + encodeURIComponent(state.repo)
        + "?path=" + encodeURIComponent(path));
      const target = parseInt(line, 10) || 1;
      const segment = data.segments.find((s) => s.start_line <= target && target <= s.end_line) || data.segments[0];
      const body = segment.content.split("\n")
        .filter((l) => !l.startsWith("// file:") && !l.startsWith("// imports:"));
      $("modal-title").textContent = path + ":" + segment.start_line + "-" + segment.end_line;
      $("modal-body").innerHTML = '<div style="padding:14px 0">' + body.map((code, i) => {
        const number = segment.start_line + i;
        return '<div class="code-line ' + (number === target ? "hl" : "") + '">'
          + '<span class="no">' + number + '</span><span class="src">' + esc(code) + "</span></div>";
      }).join("") + "</div>";
      $("overlay").classList.add("open");
      setTimeout(() => {
        const hl = document.querySelector(".code-line.hl");
        if (hl) hl.scrollIntoView({ block: "center" });
      }, 40);
    } catch (err) {
      toast("Could not open " + path + ": " + err.message, true);
    }
  }

  function autosize() {
    const box = $("question");
    box.style.height = "auto";
    box.style.height = Math.min(box.scrollHeight, 160) + "px";
  }

  $("suggestions").innerHTML = SUGGESTIONS.map((s) => '<span class="chip">' + esc(s) + "</span>").join("");
  $("suggestions").addEventListener("click", (e) => {
    if (!e.target.classList.contains("chip")) return;
    $("question").value = e.target.textContent;
    autosize();
    $("question").focus();
  });

  $("ask-btn").addEventListener("click", ask);
  $("index-btn").addEventListener("click", buildIndex);
  $("source-input").addEventListener("keydown", (e) => { if (e.key === "Enter") buildIndex(); });
  $("question").addEventListener("input", autosize);
  $("question").addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) { e.preventDefault(); ask(); }
  });
  document.addEventListener("click", (e) => {
    const node = e.target.closest(".cite, .citation");
    if (node) openSource(node.dataset.path, node.dataset.line);
  });
  $("modal-close").addEventListener("click", () => $("overlay").classList.remove("open"));
  $("overlay").addEventListener("click", (e) => { if (e.target === $("overlay")) $("overlay").classList.remove("open"); });
  document.addEventListener("keydown", (e) => { if (e.key === "Escape") $("overlay").classList.remove("open"); });

  loadHealth();
  loadIndexes();
})();
